"""Random (value, fallback) pairs, value sometimes present and sometimes
the null sentinel."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    rows = []
    for _ in range(4):
        fallback = rng.randint(-1000, 1000)
        if rng.random() < 0.5:
            rows.append("null %d" % fallback)
        else:
            value = rng.randint(-1000, 1000)
            rows.append("%d %d" % (value, fallback))
    return {"name": "a mix of present and absent values #%d" % index,
            "stdin": "\n".join(rows) + "\n"}
